<?php
declare(strict_types=1);
require_once __DIR__.'/../config/app.php';require_once APP_ROOT.'/core/auth.php';$user=require_auth();$pdo=db();$resultId=(int)($_GET['id']??0);
$stmt=$pdo->prepare("SELECT r.*,e.title,e.total_points,e.teacher_id,e.class_id,c.name class_name,s.name subject_name,st.name student_name,st.enrollment FROM results r JOIN exams e ON e.id=r.exam_id JOIN classes c ON c.id=e.class_id JOIN subjects s ON s.id=e.subject_id JOIN students st ON st.id=r.student_id WHERE r.id=?");$stmt->execute([$resultId]);$result=$stmt->fetch();if(!$result){http_response_code(404);exit('Resultado não encontrado.');}if($user['role']!=='admin'&&(int)$result['teacher_id']!==(int)$user['id']){http_response_code(403);require APP_ROOT.'/partials/403.php';exit;}
$stmt=$pdo->prepare('SELECT question_number,selected_option,correct_option,is_correct,confidence FROM result_answers WHERE result_id=? ORDER BY question_number');$stmt->execute([$resultId]);$answers=$stmt->fetchAll();
$pageTitle='Resultado do aluno';require APP_ROOT.'/partials/header.php';
?>
<div class="page-toolbar reveal"><div><a class="back-link" href="<?= e(url('exams/view.php?id='.$result['exam_id'])) ?>">← <?= e($result['title']) ?></a><span class="eyebrow"><?= e($result['subject_name']) ?> • <?= e($result['class_name']) ?></span><h2><?= e($result['student_name']) ?></h2><p>Matrícula <?= e($result['enrollment']) ?> • Corrigido em <?= date('d/m/Y H:i',strtotime($result['scanned_at'])) ?></p></div><div class="score-hero"><span>NOTA</span><strong><?= format_score((float)$result['score']) ?></strong><small>de <?= format_score((float)$result['total_points']) ?></small></div></div>
<section class="stats-grid compact-stats stagger"><article class="stat-card"><div class="stat-icon green">✓</div><div><span>Acertos</span><strong><?= (int)$result['correct_count'] ?></strong><small>questões</small></div></article><article class="stat-card"><div class="stat-icon amber">×</div><div><span>Erros</span><strong><?= (int)$result['incorrect_count'] ?></strong><small>questões</small></div></article><article class="stat-card"><div class="stat-icon blue">○</div><div><span>Em branco</span><strong><?= (int)$result['blank_count'] ?></strong><small>questões</small></div></article><article class="stat-card"><div class="stat-icon purple">≈</div><div><span>Confiança</span><strong><?= $result['scanner_confidence']!==null?number_format((float)$result['scanner_confidence'],0).'%':'—' ?></strong><small>da leitura</small></div></article></section>
<section class="panel reveal"><div class="panel-head"><div><span class="eyebrow">DETALHES</span><h3>Questão por questão</h3></div></div><div class="answer-review-grid"><?php foreach($answers as $a): ?><div class="answer-review <?= (int)$a['is_correct']?'correct':'wrong' ?>"><span class="review-q"><?= (int)$a['question_number'] ?></span><div><small>Marcada</small><strong><?= e($a['selected_option']?:'—') ?></strong></div><div><small>Correta</small><strong><?= e($a['correct_option']) ?></strong></div><b><?= (int)$a['is_correct']?'✓':'×' ?></b></div><?php endforeach; ?></div></section>
<?php require APP_ROOT.'/partials/footer.php'; ?>
